CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 TEXT NOT NULL DEFAULT 0) STRICT;
INSERT OR IGNORE INTO t0(c0, c1) VALUES('café', 'NULL');
INSERT OR IGNORE INTO t0(c0, c1) VALUES('gamma', 'upsilon');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL CHECK(c0 IS NULL OR length(c0) < 40), c1 BLOB NOT NULL DEFAULT 0, c2 INTEGER, c3 REAL UNIQUE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES('alpha', x'421f6d', 3.141592653589793, -3, 2);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 INTEGER, c1 INTEGER COLLATE NOCASE, c2 INTEGER, c3 INTEGER UNIQUE) STRICT;
INSERT OR IGNORE INTO t2(c0, c1, c2, c3) VALUES(-59, 474, 94, -122);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3) VALUES(478, -397, -38, 41);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3) VALUES(258, 336, -405, -403);
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', 2, 5), instr('a%b', 'omicron'), replace('a%b', 'é', ''), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '_', 'a%b' GLOB '*', char(74, 855), 'a%b' || 'omicron', 'a%b' < 'omicron', 'a%b' = 'omicron' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 1, 4), instr('zeta', 'pi'), replace('zeta', 'é', ''), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '%a_', 'zeta' GLOB '?', char(70, 700), 'zeta' || 'pi', 'zeta' < 'pi', 'zeta' = 'pi' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', -1, 2), instr('Lambda', 'Lambda'), replace('Lambda', 'a', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%', 'Lambda' GLOB '?', char(67, 880), 'Lambda' || 'Lambda', 'Lambda' < 'Lambda', 'Lambda' = 'Lambda' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -3, 3), instr('alpha', 'omega'), replace('alpha', 'é', ''), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%a_', 'alpha' GLOB '?', char(82, 579), 'alpha' || 'omega', 'alpha' < 'omega', 'alpha' = 'omega' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 4, 1), instr('phi', 'Ελλάδα'), replace('phi', 'é', 'XY'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '_', 'phi' GLOB '?', char(84, 454), 'phi' || 'Ελλάδα', 'phi' < 'Ελλάδα', 'phi' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', 4, 1), instr('alpha', 'omicron'), replace('alpha', 'e', 'XY'), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%é%', 'alpha' GLOB '*', char(83, 748), 'alpha' || 'omicron', 'alpha' < 'omicron', 'alpha' = 'omicron' COLLATE NOCASE;
SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t1 WHERE CAST(iif(id, c1, '-7') AS BLOB);
SELECT c2, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c2 HAVING count(*) > 2 ORDER BY c2;
SELECT count(*), count(c0), sum(c0), total(c0), avg(c0), min(c0), max(c0), count(DISTINCT c0) FROM t0 WHERE NOT NOT x'b7a85307';
SELECT c0, count(*), group_concat(id, ';') FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c0 ORDER BY c0;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', -2, 2), instr('-7', 'sigma'), replace('-7', 'a', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE 'A%', '-7' GLOB '*', char(86, 830), '-7' || 'sigma', '-7' < 'sigma', '-7' = 'sigma' COLLATE NOCASE;
